```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology modelling securities, debt, equity, hybrid instruments, derivatives, funds and related accounting classifications, derived from corpus text on financial instruments." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:Asset a owl:Class ;
  rdfs:label "Asset" ;
  rdfs:comment "A generic class of things that can underlie or constitute financial value, including financial instruments, commodities, currencies and indices." .

fis:FinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Financial Instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled (IAS 32)." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Cash Instrument" ;
  rdfs:comment "A financial instrument whose value is determined directly by markets; includes securities, loans and deposits." .

fis:DerivativeInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Derivative Instrument" ;
  rdfs:comment "A financial instrument which derives its value from the value and characteristics of one or more underlying entities." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Asset ]
    )
  ] .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Commodity" .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Currency" .
fis:Index a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Index" .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Interest Rate" .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Loan" ;
  rdfs:comment "A cash instrument such as a loan or deposit where both borrower and lender have to agree on a transfer (not readily transferable)." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument ; rdfs:label "Deposit" .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Security" ;
  rdfs:comment "A tradable financial asset; a negotiable cash instrument. NOTE: some US sources (e.g. categorisation into debt/equity/derivatives securities) treat derivatives as a kind of security, while the cash-vs-derivative-instrument split treats them as a disjoint category. This ontology follows the majority/cash-instrument view and records the conflict here." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:CashInstrument
      [ a owl:Restriction ; owl:onProperty fis:isNegotiable ; owl:hasValue true ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:Security fis:Loan fis:Deposit ) ] .
owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:DerivativeInstrument ) ] .

#################################################################
# ENTITIES: ISSUERS AND HOLDERS
#################################################################

fis:Entity a owl:Class ; rdfs:label "Entity" .

fis:Issuer a owl:Class ;
  rdfs:subClassOf fis:Entity ;
  rdfs:label "Issuer" ;
  rdfs:comment "The company or other entity issuing a security." .

fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Corporation" .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Bank" .

fis:Government a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "Government" .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Government ;
  rdfs:label "Sovereign Government" .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Government ;
  rdfs:label "Local Government" ;
  rdfs:comment "State, provincial, territorial, municipal or other governmental unit other than a sovereign government." .

owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:LocalGovernment ) ] .

fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:label "Supranational Organization" ;
  rdfs:comment "E.g. the World Bank, the IMF, regional multilateral development banks." .

fis:Holder a owl:Class ; rdfs:subClassOf fis:Entity ; rdfs:label "Holder" .
fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Holder ; rdfs:label "Bondholder" .
fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Holder ;
  rdfs:label "Shareholder" ;
  rdfs:comment "An individual or company that legally owns one or more shares of stock." .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range fis:Issuer ;
  rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ;
  rdfs:range fis:FinancialInstrument ;
  rdfs:label "is issuer of" .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range fis:Holder ;
  rdfs:label "has holder" .

fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Holder ;
  rdfs:range fis:FinancialInstrument ;
  rdfs:label "is holder of" .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ;
  rdfs:range fis:Asset ;
  rdfs:label "has underlying" .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ;
  rdfs:range fis:FinancialInstrument ;
  rdfs:label "is underlying of" .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:DebtSecurity ;
  rdfs:range fis:Asset ;
  rdfs:label "has collateral" .

fis:isCollateralOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ;
  rdfs:range fis:DebtSecurity ;
  rdfs:label "is collateral of" .

fis:hasConversionTarget a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:HybridSecurity ;
  rdfs:range fis:EquitySecurity ;
  rdfs:label "has conversion target" ;
  rdfs:comment "Relates a convertible security to the equity security it may be converted into." .

fis:isConversionTargetOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasConversionTarget ;
  rdfs:domain fis:EquitySecurity ;
  rdfs:range fis:HybridSecurity ;
  rdfs:label "is conversion target of" .

fis:hasComponent a owl:ObjectProperty ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Security ;
  rdfs:label "has component" ;
  rdfs:comment "Relates a hybrid security to the debt-like and equity-like security characteristics it combines." .

fis:hasDividend a owl:ObjectProperty ;
  rdfs:domain fis:Stock ;
  rdfs:range fis:Dividend ;
  rdfs:label "has dividend" .

fis:isDividendOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasDividend ;
  rdfs:domain fis:Dividend ;
  rdfs:range fis:Stock ;
  rdfs:label "is dividend of" .

fis:hasTranche a owl:ObjectProperty ;
  rdfs:domain fis:AssetBackedSecurity ;
  rdfs:range fis:Tranche ;
  rdfs:label "has tranche" .

fis:isTrancheOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasTranche ;
  rdfs:domain fis:Tranche ;
  rdfs:range fis:AssetBackedSecurity ;
  rdfs:label "is tranche of" .

fis:hasReferenceEntity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CreditDefaultSwap ;
  rdfs:range fis:Issuer ;
  rdfs:label "has reference entity" .

fis:isReferenceEntityOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasReferenceEntity ;
  rdfs:domain fis:Issuer ;
  rdfs:range fis:CreditDefaultSwap ;
  rdfs:label "is reference entity of" .

fis:hasHolding a owl:ObjectProperty ;
  rdfs:domain fis:Fund ;
  rdfs:range fis:Security ;
  rdfs:label "has holding" ;
  rdfs:comment "Relates a fund to securities held in its portfolio." .

fis:isHoldingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolding ;
  rdfs:domain fis:Security ;
  rdfs:range fis:Fund ;
  rdfs:label "is holding of" .

fis:hasTrackedIndex a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Fund ;
  rdfs:range fis:Index ;
  rdfs:label "has tracked index" .

fis:hasContractualRightToReceive a owl:ObjectProperty ;
  rdfs:domain fis:FinancialAsset ;
  rdfs:range fis:FinancialInstrument ;
  rdfs:label "has contractual right to receive" .

fis:hasContractualObligationToDeliver a owl:ObjectProperty ;
  rdfs:domain fis:FinancialLiability ;
  rdfs:range fis:FinancialInstrument ;
  rdfs:label "has contractual obligation to deliver" .

fis:hasOwnershipInterestIn a owl:ObjectProperty ;
  rdfs:domain fis:EquityInstrument ;
  rdfs:range fis:Entity ;
  rdfs:label "has ownership interest in" .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:isNegotiable a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:CashInstrument ; rdfs:range xsd:boolean ; rdfs:label "is negotiable" .

fis:hasResidualClaim a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ;
  rdfs:label "has residual claim" ;
  rdfs:comment "True for equity securities (residual claim on assets after creditors); false for debt securities (fixed claim to principal and interest)." .

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date ; rdfs:label "has maturity date" .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "has face value" ;
  rdfs:comment "Also called par, principal or nominal amount." .

fis:hasCouponRate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ; rdfs:label "has coupon rate" .

fis:hasCouponType a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:string ;
  rdfs:label "has coupon type" ;
  rdfs:comment "Value 'fixed' or 'floating'." .

fis:hasYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ; rdfs:label "has yield" .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string ; rdfs:label "has credit rating" .

fis:hasConversionRatio a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:HybridSecurity ; rdfs:range xsd:decimal ; rdfs:label "has conversion ratio" .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ; rdfs:label "has strike price" .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:date ; rdfs:label "has expiration date" .

fis:hasPremium a owl:DatatypeProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ; rdfs:label "has premium" .

fis:hasOptionType a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ;
  rdfs:label "has option type" ;
  rdfs:comment "Value 'call' or 'put'." .

fis:hasExerciseStyle a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ;
  rdfs:label "has exercise style" ;
  rdfs:comment "Value 'American', 'European' or 'Bermudan'." .

fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:date ; rdfs:label "has delivery date" .

fis:isExchangeTraded a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:boolean ; rdfs:label "is exchange traded" .

fis:isStandardized a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:boolean ; rdfs:label "is standardized" .

fis:hasNotionalAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Swap ; rdfs:range xsd:decimal ; rdfs:label "has notional amount" .

fis:hasVotingRights a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:boolean ; rdfs:label "has voting rights" .

fis:hasParValue a owl:DatatypeProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:decimal ; rdfs:label "has par value" .

fis:isCallable a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean ; rdfs:label "is callable" .

fis:isPutable a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean ; rdfs:label "is putable" .

fis:isSecured a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:boolean ; rdfs:label "is secured" .

fis:hasSeniority a owl:DatatypeProperty ;
  rdfs:range xsd:string ;
  rdfs:label "has seniority" ;
  rdfs:comment "Value 'senior' or 'subordinated'. Applicable to debt securities and tranches." .

fis:isRegistered a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ; rdfs:label "is registered" .

fis:isNonCertificated a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ; rdfs:label "is non-certificated" .

fis:hasDivisionType a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string ;
  rdfs:comment "Value 'divided' or 'undivided'." ;
  rdfs:label "has division type" .

fis:isFungible a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean ; rdfs:label "is fungible" .

fis:hasDividendAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Dividend ; rdfs:range xsd:decimal ; rdfs:label "has dividend amount" .

fis:hasBusinessModel a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range xsd:string ; rdfs:label "has business model" .

fis:satisfiesSPPICriterion a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range xsd:boolean ;
  rdfs:label "satisfies SPPI criterion" ;
  rdfs:comment "Whether contractual cash flows are solely payments of principal and interest (IFRS 9)." .

#################################################################
# SECURITY TAXONOMY: DEBT / EQUITY / HYBRID
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:label "Debt Security" ;
  rdfs:comment "A security under which the holder is entitled to payment of principal and interest; also called bonds, debentures, notes, deposits or commercial paper depending on maturity and collateral." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasResidualClaim ; owl:hasValue false ]
    )
  ] .

fis:EquitySecurity a owl:Class ;
  rdfs:label "Equity Security" ;
  rdfs:comment "A share of equity interest in an entity; holders share only in the residual interest after creditors have been paid." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasResidualClaim ; owl:hasValue true ]
    )
  ] .

fis:HybridSecurity a owl:Class ;
  rdfs:label "Hybrid Security" ;
  rdfs:comment "Combines some of the characteristics of both debt and equity securities." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasComponent ; owl:someValuesFrom fis:DebtSecurity ]
      [ a owl:Restriction ; owl:onProperty fis:hasComponent ; owl:someValuesFrom fis:EquitySecurity ]
    )
  ] .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity fis:HybridSecurity fis:DerivativeInstrument ) ] .

#################################################################
# CERTIFICATE FORM / DIVISION / FUNGIBILITY
#################################################################

fis:BearerSecurity a owl:Class ;
  rdfs:label "Bearer Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:isRegistered ; owl:hasValue false ] ) ] .

fis:RegisteredSecurity a owl:Class ;
  rdfs:label "Registered Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:isRegistered ; owl:hasValue true ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

fis:BookEntrySecurity a owl:Class ;
  rdfs:label "Book Entry Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:isNonCertificated ; owl:hasValue true ] ) ] .

fis:DividedSecurity a owl:Class ;
  rdfs:label "Divided Security" ;
  rdfs:comment "Each divided security constitutes a separate asset, legally distinct from each other security in the same issue." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasDivisionType ; owl:hasValue "divided" ] ) ] .

fis:UndividedSecurity a owl:Class ;
  rdfs:label "Undivided Security" ;
  rdfs:comment "The entire issue makes up one single asset, with each security a fractional part of this whole." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasDivisionType ; owl:hasValue "undivided" ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:FungibleSecurity a owl:Class ;
  rdfs:label "Fungible Security" ;
  rdfs:comment "All holdings of the security are treated identically and are interchangeable." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:isFungible ; owl:hasValue true ] ) ] .

#################################################################
# BONDS
#################################################################

fis:Bond a owl:Class ;
  rdfs:label "Bond" ;
  rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to provide cash flow, typically repaying principal at maturity plus interest (coupon)." ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:DebtSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:someValuesFrom xsd:decimal ]
    )
  ] .

fis:Debenture a owl:Class ;
  rdfs:label "Debenture" ;
  rdfs:comment "An unsecured bond, backed only by the general creditworthiness of the issuer." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isSecured ; owl:hasValue false ] ) ] .

fis:GovernmentBond a owl:Class ;
  rdfs:label "Government Bond" ;
  rdfs:comment "Also called sovereign bond or treasury bond: a bond issued by a sovereign national government." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:MunicipalBond a owl:Class ;
  rdfs:label "Municipal Bond" ;
  rdfs:comment "A bond issued by state or local governments, or entities they create such as authorities and special districts." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] .

fis:SupranationalBond a owl:Class ;
  rdfs:label "Supranational Bond" ;
  rdfs:comment "Also known as a 'supra'; issued by a supranational organisation such as the World Bank." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:CorporateBond a owl:Class ;
  rdfs:label "Corporate Bond" ;
  rdfs:comment "A bond issued by a corporation to raise financing for operations, mergers and acquisitions, or expansion." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) ] .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:label "General Obligation Bond" ;
  rdfs:comment "Principal and interest secured by the full faith and credit of the issuer." .

fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:label "Revenue Bond" ;
  rdfs:comment "Repayment guaranteed solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .

fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:label "Assessment Bond" .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "High Yield Bond" ;
  rdfs:comment "Also called junk bond: rated below investment grade by credit rating agencies." .

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "Investment Grade Bond" .

owl:AllDisjointClasses [ owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) ] .

fis:FixedRateBond a owl:Class ;
  rdfs:label "Fixed Rate Bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "fixed" ] ) ] .

fis:FloatingRateNote a owl:Class ;
  rdfs:label "Floating Rate Note" ;
  rdfs:comment "Also called FRN or floater; coupon is linked to a reference rate of interest such as LIBOR/SOFR or Euribor." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "floating" ] ) ] .

fis:ZeroCouponBond a owl:Class ;
  rdfs:label "Zero Coupon Bond" ;
  rdfs:comment "A bond in which the face value is repaid at maturity and which pays no periodic interest." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0"^^xsd:decimal ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "Perpetual Bond" ;
  rdfs:comment "Also called a perpetuity or 'Perp'; has no maturity date." .

fis:ConvertibleBond a owl:Class ;
  rdfs:label "Convertible Bond" ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "A bond that the holder can convert into a specified number of shares of the issuer's common stock." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:HybridSecurity, fis:Bond ;
  rdfs:label "Exchangeable Bond" ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

fis:CallableBond a owl:Class ;
  rdfs:label "Callable Bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue true ] ) ] .

fis:PutableBond a owl:Class ;
  rdfs:label "Putable Bond" ;
  rdfs:comment "Also called retractable bond." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue true ] ) ] .

fis:BulletBond a owl:Class ;
  rdfs:label "Bullet Bond" ;
  rdfs:comment "A straight bond that is neither callable nor putable." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue false ]
      [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue false ] ) ] .

fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BearerSecurity ;
  rdfs:label "Bearer Bond" .

fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:RegisteredSecurity ;
  rdfs:label "Registered Bond" .

fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BookEntrySecurity ;
  rdfs:label "Book Entry Bond" .

owl:AllDisjointClasses [ owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) ] .

fis:SeniorDebt a owl:Class ;
  rdfs:label "Senior Debt" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "senior" ] ) ] .

fis:SubordinatedBond a owl:Class ;
  rdfs:label "Subordinated Bond" ;
  rdfs:comment "Has a lower priority than other bonds of the issuer in case of liquidation." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "subordinated" ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:SeniorDebt fis:SubordinatedBond ) ] .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "Covered Bond" ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets; unlike ABS, the assets remain on the issuer's balance sheet." .

fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "Serial Bond" ;
  rdfs:comment "A bond that matures in installments over a period of time." .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED SECURITIES
#################################################################

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "Mortgage" .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "Residential Mortgage" .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "Commercial Mortgage" .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .

fis:DebtObligation a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:label "Debt Obligation" ;
  rdfs:comment "Generic pooled debt obligations, including other asset-backed securities, used as collateral for a CDO." .

fis:Tranche a owl:Class ;
  rdfs:label "Tranche" ;
  rdfs:comment "A slice of an asset-backed security with a given level of seniority in the debt repayment stream." .

fis:AssetBackedSecurity a owl:Class ;
  rdfs:label "Asset Backed Security" ;
  rdfs:comment "A bond backed by a pool of assets other than a single issuer's general credit." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ) ] .

fis:MortgageBackedSecurity a owl:Class ;
  rdfs:label "Mortgage Backed Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  rdfs:label "Residential Mortgage Backed Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .

fis:CommercialMortgageBackedSecurity a owl:Class ;
  rdfs:label "Commercial Mortgage Backed Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "Collateralized Mortgage Obligation" ;
  rdfs:comment "Also called a pay-through bond; typically divided into classes with different maturities and priorities." .

fis:CollateralizedDebtObligation a owl:Class ;
  rdfs:label "Collateralized Debt Obligation" ;
  rdfs:comment "A type of structured asset-backed security backed by a pool of bonds or other debt obligations." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligation ] ) ] .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Money Market Instrument" ;
  rdfs:comment "A short term debt instrument with an original maturity of one year or less." .

fis:CommercialPaper a owl:Class ;
  rdfs:label "Commercial Paper" ;
  rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:isSecured ; owl:hasValue false ] ) ] .

fis:CertificateOfDeposit a owl:Class ;
  rdfs:label "Certificate Of Deposit" ;
  rdfs:comment "A time deposit sold by banks, thrift institutions, and credit unions." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ] ) ] .

fis:TreasuryBill a owl:Class ;
  rdfs:label "Treasury Bill" ;
  rdfs:comment "Zero-coupon government debt obligations that mature in one year or less." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0"^^xsd:decimal ] ) ] .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Repurchase Agreement" ;
  rdfs:comment "Borrowing money by combining the sale of an asset with a subsequent repurchase at a higher price. Explicitly noted as an instrument that defies the cash/derivative categorisation matrix." .

#################################################################
# STOCKS / SHARES
#################################################################

fis:Stock a owl:Class ;
  rdfs:label "Stock" ;
  rdfs:comment "Also called share or capital stock: consists of all the shares by which ownership of a corporation is divided." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:CommonStock a owl:Class ;
  rdfs:label "Common Stock" ;
  rdfs:comment "Also called ordinary share or voting share; typically carries voting rights." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasVotingRights ; owl:hasValue true ] ) ] .

fis:PreferredStock a owl:Class ;
  rdfs:label "Preferred Stock" ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "Also called preference share; typically does not carry voting rights but has priority over common stock in dividends and liquidation. NOTE: cumulative preferred shares may gain voting rights when dividends are in arrears, so hasVotingRights=false is the typical/majority case, not absolute." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasVotingRights ; owl:hasValue false ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
  rdfs:label "Convertible Preferred Stock" ;
  rdfs:comment "Preferred stock that includes the ability to convert into a fixed number of common shares." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "Cumulative Preferred Stock" ;
  rdfs:comment "Unpaid dividends accumulate and must be paid before common-stock dividends resume." .

fis:NonCumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "Non Cumulative Preferred Stock" ;
  rdfs:comment "Also called straight preferred; passed dividends are lost." .

owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NonCumulativePreferredStock ) ] .

fis:Dividend a owl:Class ;
  rdfs:label "Dividend" ;
  rdfs:comment "A discretionary distribution of a company's profit paid to shareholders." .

#################################################################
# HYBRID / CONVERTIBLE SECURITIES, WARRANTS, DEPOSITARY RECEIPTS
#################################################################

fis:PreferenceShare a owl:Class ; owl:equivalentClass fis:PreferredStock ;
  rdfs:label "Preference Share" ;
  rdfs:comment "Synonym for PreferredStock (UK terminology)." .

fis:DepositaryReceipt a owl:Class ;
  rdfs:label "Depositary Receipt" ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ]
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "American Depositary Receipt" ;
  rdfs:comment "Depositary receipts that are listed and traded in the United States." .

fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "European Depositary Receipt" .

fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "Global Depositary Receipt" .

owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# DERIVATIVES
#################################################################

fis:LockDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "Lock Derivative" ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .

fis:OptionDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "Option Derivative" ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .

owl:AllDisjointClasses [ owl:members ( fis:LockDerivative fis:OptionDerivative ) ] .

fis:Forward a owl:Class ;
  rdfs:subClassOf fis:LockDerivative ;
  rdfs:label "Forward" ;
  rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DerivativeInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasDeliveryDate ; owl:someValuesFrom xsd:date ]
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] .

fis:Future a owl:Class ;
  rdfs:subClassOf fis:LockDerivative ;
  rdfs:label "Future" ;
  rdfs:comment "A standardized contract between two parties to buy or sell a specified asset for a price agreed today, with delivery at a specified future date, traded on a futures exchange." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DerivativeInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasDeliveryDate ; owl:someValuesFrom xsd:date ]
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ]
      [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:Option a owl:Class ;
  rdfs:subClassOf fis:OptionDerivative ;
  rdfs:label "Option" ;
  rdfs:comment "A contract which gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DerivativeInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ]
      [ a owl:Restriction ; owl:onProperty fis:hasExpirationDate ; owl:someValuesFrom xsd:date ] ) ] .

fis:CallOption a owl:Class ;
  rdfs:label "Call Option" ;
  rdfs:comment "The right (not obligation) to buy an asset at a fixed price in the future." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ] ) ] .

fis:PutOption a owl:Class ;
  rdfs:label "Put Option" ;
  rdfs:comment "The right (not obligation) to sell an asset at a fixed price in the future." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ;
  rdfs:label "American Option" ;
  rdfs:comment "May be exercised on any trading day on or before expiration." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] .

fis:EuropeanOption a owl:Class ;
  rdfs:label "European Option" ;
  rdfs:comment "May only be exercised on the expiry date." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] .

fis:BermudanOption a owl:Class ;
  rdfs:label "Bermudan Option" ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

fis:StockOption a owl:Class ;
  rdfs:label "Stock Option" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] .

fis:StockFuture a owl:Class ;
  rdfs:label "Stock Future" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Future
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] .

fis:Warrant a owl:Class ;
  rdfs:label "Warrant" ;
  rdfs:comment "A long-dated option issued by the company that allows the holder to purchase a specific number of shares at a specified price within a specified time; also called equity warrant." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:Swap a owl:Class ;
  rdfs:subClassOf fis:LockDerivative ;
  rdfs:label "Swap" ;
  rdfs:comment "A derivative in which two counterparties exchange cash flows of one party's financial instrument for those of the other party's, calculated over a notional principal amount." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DerivativeInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasNotionalAmount ; owl:someValuesFrom xsd:decimal ] ) ] .

fis:InterestRateSwap a owl:Class ;
  rdfs:label "Interest Rate Swap" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRate ] ) ] .

fis:CurrencySwap a owl:Class ;
  rdfs:label "Currency Swap" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Currency ] ) ] .

fis:CreditDefaultSwap a owl:Class ;
  rdfs:label "Credit Default Swap" ;
  rdfs:comment "The seller compensates the buyer in the event of a loan default or other credit event on a reference entity's debt." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
      [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ]
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

fis:OTCDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "Over The Counter Derivative" ;
  rdfs:comment "Traded and privately negotiated directly between two parties, without going through an exchange." .

fis:ExchangeTradedDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "Exchange Traded Derivative" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DerivativeInstrument
      [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:OTCDerivative fis:ExchangeTradedDerivative ) ] .

#################################################################
# FUNDS
#################################################################

fis:Fund a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Fund" ;
  rdfs:comment "An investment vehicle that pools money from many investors to purchase securities." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasHolding ; owl:someValuesFrom fis:Security ] ) ] .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:label "Mutual Fund" ;
  rdfs:comment "Purchased from or sold to the issuer at net asset value; not typically the same as a hedge fund or ETF." .

fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:label "Exchange Traded Fund" ;
  rdfs:comment "An investment fund whose shares trade on national securities exchanges at market prices that may differ from net asset value." .

fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:label "Hedge Fund" ;
  rdfs:comment "Available only to high-net-worth/sophisticated investors; uses more flexible, risky strategies than mutual funds." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

fis:MoneyMarketFund a owl:Class ;
  rdfs:label "Money Market Fund" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
      [ a owl:Restriction ; owl:onProperty fis:hasHolding ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] .

fis:BondFund a owl:Class ;
  rdfs:label "Bond Fund" ;
  rdfs:comment "Also called income fund." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
      [ a owl:Restriction ; owl:onProperty fis:hasHolding ; owl:someValuesFrom fis:Bond ] ) ] .

fis:StockFund a owl:Class ;
  rdfs:label "Stock Fund" ;
  rdfs:comment "Also called equity fund." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
      [ a owl:Restriction ; owl:onProperty fis:hasHolding ; owl:someValuesFrom fis:Stock ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:StockFund ) ] .

fis:IndexFund a owl:Class ;
  rdfs:label "Index Fund" ;
  rdfs:comment "A passively managed fund designed to track the performance of an index." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Fund
      [ a owl:Restriction ; owl:onProperty fis:hasTrackedIndex ; owl:someValuesFrom fis:Index ] ) ] .

fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:Fund ;
  rdfs:label "Actively Managed Fund" ;
  rdfs:comment "Seeks to outperform stock market indices; generally charges higher fees than index funds." .

owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

#################################################################
# ACCOUNTING (IAS 32 / IFRS 9) CLASSIFICATION
#################################################################

fis:FinancialAsset a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Financial Asset (accounting)" ;
  rdfs:comment "IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash or another financial asset, or a contractual right to exchange financial instruments under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
  rdfs:label "Financial Liability (accounting)" ;
  rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset, or to exchange financial instruments under potentially unfavourable conditions. The critical feature distinguishing a financial liability from equity is whether the issuer has a contractual obligation to deliver cash; e.g. a mandatorily redeemable preference share is classified as a financial liability under IAS 32 even though it is commonly called 'preferred equity' in the market (fis:PreferredStock). This is a deliberate conflict between accounting substance and market terminology, noted here per corpus." .

fis:EquityInstrument a owl:Class ;
  rdfs:label "Equity Instrument (accounting)" ;
  rdfs:comment "IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities. Classification depends on the absence of a contractual obligation to deliver cash, not on the instrument's legal name; may diverge from fis:EquitySecurity for instruments such as mandatorily redeemable preference shares." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasOwnershipInterestIn ; owl:someValuesFrom fis:Entity ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:FinancialLiability fis:EquityInstrument ) ] .

fis:CompoundFinancialInstrument a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Compound Financial Instrument" ;
  rdfs:comment "Contains both a liability component and an equity component, e.g. a convertible bond under IAS 32, which must be presented split into its two components." .

fis:AmortisedCostFinancialAsset a owl:Class ;
  rdfs:label "Amortised Cost Financial Asset" ;
  rdfs:comment "IFRS 9: measured at amortised cost if held to collect contractual cash flows and the SPPI criterion is satisfied." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
      [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:hasValue "HoldToCollect" ]
      [ a owl:Restriction ; owl:onProperty fis:satisfiesSPPICriterion ; owl:hasValue true ] ) ] .

fis:FVOCIFinancialAsset a owl:Class ;
  rdfs:label "Fair Value Through OCI Financial Asset" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
      [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:hasValue "HoldToCollectAndSell" ]
      [ a owl:Restriction ; owl:onProperty fis:satisfiesSPPICriterion ; owl:hasValue true ] ) ] .

fis:FVTPLFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  rdfs:label "Fair Value Through Profit Or Loss Financial Asset" ;
  rdfs:comment "Default category for financial assets failing the SPPI test (e.g. derivatives) or equity investments not elected to FVOCI." .

owl:AllDisjointClasses [ owl:members ( fis:AmortisedCostFinancialAsset fis:FVOCIFinancialAsset fis:FVTPLFinancialAsset ) ] .
